import{makeQuestion,count,isCorrect,fmt,round}from'./questions.js';
import{mathsTools,accountingTools,calculate}from'./labs.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10l9-7 9 7v10H5V10 M9 20v-7h6v7',book:'M4 4h6l2 2 2-2h6v15h-6l-2 2-2-2H4z M12 6v15',play:'M8 4l13 8-13 8z',paper:'M6 2h9l4 4v16H6z M14 2v6h5 M9 12h7 M9 16h7',lab:'M9 2h6 M10 2v7L4 20q-1 2 2 2h12q3 0 2-2L14 9V2 M8 14h8',cards:'M4 6h16v15H4z M7 3h10 M8 11h8 M8 15h5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v6l4 2',note:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',star:'M12 2l3 7 7 1-5 5 1 7-6-4-6 4 1-7-5-5 7-1z',check:'M4 12l5 5L20 6',chart:'M4 20V4 M4 20h17 M8 16v-4 M13 16V8 M18 16V4',heart:'M12 21S1 14 3 7q3-6 9 0 6-7 9 0 2 7-9 14z',sun:'M12 3v2 M12 19v2 M3 12h2 M19 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2 M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',menu:'M4 6h16 M4 12h16 M4 18h16'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.star}"/></svg>`;
const link=(route,label,cls='button')=>`<a class="${cls}" href="#${route}">${label}</a>`;
const button=(action,label,cls='button secondary',data='')=>`<button class="${cls}" data-action="${action}" ${data}>${label}</button>`;
const safeURL=s=>{try{const u=new URL(s);return['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}};
const nowDate=()=>new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function emptyState(){return{version:1,name:'Curious mind',prefs:{},notes:{},bookmarks:[],reviewed:[],mastered:[],attempts:[],tasks:[],resources:[],days:[],exams:[],activeExam:null,timer:null};}
export function start(config,topics){
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],key=config.id+'-v1';
let storageOK=true,state;try{state=validate(JSON.parse(localStorage.getItem(key)))}catch{state=emptyState();}
function validate(s){const d=emptyState();if(!s||s.version!==1)return d;for(const k of['bookmarks','reviewed','mastered','attempts','tasks','resources','days','exams'])if(Array.isArray(s[k]))d[k]=s[k].slice(0,k==='attempts'?500:2000);d.name=String(s.name||d.name).slice(0,40);d.prefs=s.prefs&&typeof s.prefs==='object'?s.prefs:{};d.notes=s.notes&&typeof s.notes==='object'&&!Array.isArray(s.notes)?s.notes:{};d.activeExam=s.activeExam&&Array.isArray(s.activeExam.questions)&&Array.isArray(s.activeExam.answers)&&s.activeExam.questions.length<=20&&s.activeExam.questions.every(x=>topics.some(t=>t.id===x.topic)&&Number.isInteger(x.index))&&Number.isFinite(s.activeExam.ends)?s.activeExam:null;return d;}
let route=[],current=null,revealed=0,toastId,flash=0,flipped=false,flashFilter='',timerRunning=false,timerRemaining=1500,timerEnd=0,lastQuizView=false;
const main=$('#main'),tools=config.subject==='maths-literacy'?mathsTools:accountingTools;
const topic=id=>topics.find(t=>t.id===id)||topics[0];
const getQ=(id,i)=>({...makeQuestion(config.subject,topic(id),i),topic:topic(id).id,index:Math.max(0,Math.min(count(topic(id))-1,Number(i)||0)),key:topic(id).id+':'+Math.max(0,Math.min(count(topic(id))-1,Number(i)||0))});
function save(){try{localStorage.setItem(key,JSON.stringify(state));storageOK=true}catch{storageOK=false;toast('Device storage is unavailable or full. Export a backup to keep your work.');}}
function activity(){const d=nowDate();if(!state.days.includes(d))state.days.push(d);state.days=state.days.slice(-365);}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastId);toastId=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
function close(){$('#modal').close();}
function prefs(){const p=state.prefs;for(const[c,k]of[['dark','dark'],['contrast','contrast'],['reduce-motion','motion'],['blue-light','warm'],['focus','focus']])document.body.classList.toggle(c,!!p[k]);document.documentElement.style.setProperty('--font',Math.max(1,Math.min(1.25,Number(p.font)||1)));$('#theme').innerHTML=icon('sun');$('#theme').setAttribute('aria-label',p.dark?'Use light mode':'Use dark mode');save();}
function download(name,data,type='application/json'){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function heading(eye,title,desc,actions=''){return`<div class="page-head"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions no-print">${actions}</div></div>`;}
function cards(list){return list.map(t=>`<a class="topic-card" href="#topic/${t.id}"><div class="topic-symbol">${t.symbol}</div><div class="eyebrow">${t.paper?'PAPER '+t.paper:'FOUNDATIONS · BOTH PAPERS'}</div><h3>${t.title}</h3><p>${esc(t.summary.split('. ')[0])}.</p><div class="card-bottom"><span>${count(t)} ${t.id==='ethics'?'scenarios':'practice variations'}</span><b>${state.reviewed.includes(t.id)?'Reviewed ✓':'Let’s explore ↗'}</b></div></a>`).join('');}
function stat(symbol,value,label){return`<div class="stat"><span class="stat-icon">${icon(symbol)}</span><div><strong>${value}</strong><small>${label}</small></div></div>`;}
function heroArt(){return config.subject==='maths-literacy'?`<svg viewBox="0 0 350 285" aria-label="Illustrated shopping receipt, ruler and calculator" role="img"><g transform="rotate(-9 160 130)"><rect x="56" y="20" width="178" height="232" rx="9" fill="#fffdf5" stroke="#bccfc1"/><path d="M73 60h142 M73 88h96 M73 111h75 M73 134h89 M73 166h141" stroke="#bfd0c3" stroke-width="2"/><text x="78" y="47" fill="#315842" font-family="monospace" font-size="11">LITTLE WINS MARKET</text><text x="178" y="90" fill="#315842" font-size="11">R24</text><text x="178" y="113" fill="#315842" font-size="11">R18</text><text x="178" y="136" fill="#315842" font-size="11">R12</text><text x="78" y="192" fill="#315842" font-size="12">TOTAL</text><text x="170" y="192" fill="#315842" font-weight="bold" font-size="16">R54</text><path d="M91 217h98" stroke="#315842" stroke-width="2" stroke-dasharray="2 3"/></g><g transform="rotate(9 253 170)"><rect x="191" y="111" width="115" height="149" rx="14" fill="#2a7158"/><rect x="205" y="127" width="87" height="35" rx="5" fill="#dfecc7"/><text x="219" y="151" fill="#315842" font-family="monospace" font-size="19">54.00</text>${[0,1,2].map(r=>[0,1,2,3].map(c=>`<rect x="${205+c*23}" y="${176+r*25}" width="17" height="16" rx="4" fill="${c===3?'#efcf71':'#e6f0e9'}"/>`).join('')).join('')}</g><circle cx="52" cy="222" r="22" fill="#edcc72"/><text x="43" y="229" fill="#75612b" font-size="22">R</text><path d="M276 43l5 12 13 2-10 8 2 13-10-7-12 6 3-13-9-9 13-1z" fill="#edcc72"/></svg>`:`<svg viewBox="0 0 350 285" aria-label="Illustrated accounting ledger with equal debit and credit totals" role="img"><g transform="rotate(-7 160 140)"><rect x="48" y="25" width="246" height="225" rx="10" fill="#fffdf8" stroke="#cec3df"/><rect x="48" y="25" width="246" height="43" rx="10" fill="#6954a2"/><path d="M48 58h246" stroke="#6954a2" stroke-width="20"/><text x="68" y="52" fill="#fff" font-size="12" font-family="monospace">SMALL VICTORIES LTD.</text><path d="M66 101h210 M66 133h210 M66 165h210 M66 197h210 M172 82v143" stroke="#ddd4e9"/><text x="85" y="91" fill="#6954a2" font-size="11">DEBIT</text><text x="204" y="91" fill="#6954a2" font-size="11">CREDIT</text><text x="81" y="124" fill="#645574" font-size="13">5 000</text><text x="201" y="124" fill="#645574" font-size="13">5 000</text><text x="81" y="157" fill="#645574" font-size="13">1 200</text><text x="201" y="157" fill="#645574" font-size="13">1 200</text><text x="80" y="221" fill="#6954a2" font-size="16" font-weight="bold">6 200</text><text x="200" y="221" fill="#6954a2" font-size="16" font-weight="bold">6 200</text></g><g transform="rotate(12 290 220)"><rect x="248" y="161" width="68" height="83" rx="13" fill="#ecd383"/><path d="M264 203l12 12 24-27" stroke="#71612c" stroke-width="5" fill="none" stroke-linecap="round"/></g><circle cx="46" cy="67" r="17" fill="#dfd1f2"/><text x="37" y="74" fill="#6954a2" font-size="24">=</text></svg>`;}
function home(){const attempted=state.attempts.length,accuracy=attempted?Math.round(state.attempts.filter(x=>x.correct).length/attempted*100):0,done=state.reviewed.length;return`<div class="welcome"><p>A little progress looks good on you, <b>${esc(state.name)}</b>.</p><span class="pill">GRADE 12 · SOUTH AFRICA</span></div><section class="hero"><div><div class="eyebrow">${config.label} · YOUR STUDY STUDIO</div><h1>${config.hero}</h1><p>${config.intro}</p><div class="actions">${link('learn','Find my starting point ↗')}${link('lab','Explore the lab','ghost')}</div></div><div class="hero-art">${heroArt()}<span class="art-sticker">${config.sticker}</span></div></section><div class="stats">${stat('book',done+'/'+topics.length,'topics reviewed')}${stat('check',state.mastered.length,'questions mastered')}${stat('chart',attempted?accuracy+'%':'—','practice accuracy')}${stat('star',state.days.length,'study days collected')}</div><div class="section-head"><div><div class="eyebrow">YOUR NEXT LITTLE AHA</div><h2>Where shall we begin?</h2><p>Choose a familiar place. Or a fresh start.</p></div>${link('learn','All '+topics.length+' topics ↗','text-link')}</div><div class="grid">${cards(topics.slice(0,6))}</div><div class="home-lower"><section class="feature-card"><div class="eyebrow">THE FIVE-MINUTE WIN</div><h3>One question is a good beginning.</h3><p>A fresh question, a little working space, and a solution you can unfold one line at a time.</p>${link('practice/'+topics[0].id+'/0','Give it a go ↗','button secondary small')}</section><section class="feature-card alt"><div class="eyebrow">MEET ${config.buddy.toUpperCase()}</div><h3>Your “wait, why?” buddy.</h3><p>Pick the bit that feels fuzzy. ${config.buddy} will point you to a clear explanation and a small next step.</p>${link('buddy','Untangle a topic ↗','text-link')}</section></div>${state.activeExam?`<div class="callout">Your mini mock is still running. ${link('exam','Resume it ↗','text-link')}</div>`:''}`;}
function learn(){return heading('LEARN & PRACTISE','Small steps. Solid understanding.','A clear idea first. A worked example next. You can start anywhere.')+`<div class="toolbar no-print"><input id="topic-search" type="search" placeholder="Search topics, formulas or ideas…" aria-label="Search topics"><select id="paper-filter" aria-label="Filter topics by paper"><option value="all">Both papers</option><option value="1">Paper 1</option><option value="2">Paper 2</option></select></div><div class="grid" id="topic-grid">${cards(topics)}</div><div class="callout">Paper 1: ${config.paper1}. Paper 2: ${config.paper2}. Foundation topics support both papers.${config.subject==='maths-literacy'?' Finance skills may also appear in Paper 2 contexts.':''}</div><p class="status-line">Practice includes different numerical versions of structured question types, plus concept checks. Use official papers for full examination breadth.</p>`;}
function topicPage(){const t=topic(route[1]);return heading(t.paper?'PAPER '+t.paper:'FOUNDATIONS · BOTH PAPERS',t.title,'Make room for the idea. The calculations come next.',link('practice/'+t.id+'/0','Try a question ↗'))+`<div class="tabs no-print">${link('learn','← All topics','')}${link('videos/'+t.id,'Find video lessons','')}${link('papers','Past papers','')}${button('speak','Read lesson aloud','','data-topic="'+t.id+'"')}${button('stop-speech','Stop reading','')}</div><div class="columns"><section><article class="panel"><div class="topic-symbol">${t.symbol}</div><h2>The idea, without the fog.</h2><p>${esc(t.summary)}</p><div class="formula">${esc(t.formula)}</div>${t.lessons.map(([h,p])=>`<h3>${esc(h)}</h3><p>${esc(p)}</p>`).join('')}<div class="callout warm"><b>Watch this little trap.</b><br>${esc(t.trap)}</div><div class="callout"><b>A memory nudge</b><br>${esc(t.memory)}</div><small>Original practice notes · Simoné Govender</small></article><section class="panel no-print"><h3>Your own “aha” notes</h3><form id="note-form"><label>What helped this click?<textarea name="text" maxlength="20000" placeholder="Explain it to future you…">${esc(state.notes[t.id]||'')}</textarea></label><div class="actions" style="margin-top:12px"><button class="button" type="submit">Save my note</button>${button('bookmark-topic',state.bookmarks.includes(t.id)?'Saved ✓':'Save topic','button secondary','data-topic="'+t.id+'"')}</div></form></section></section><aside><section class="panel"><h3>Your small-step route</h3><p>1. Read the idea.<br>2. Try one question.<br>3. Unfold the solution.<br>4. Try a fresh version.</p><div class="actions no-print">${button('review',state.reviewed.includes(t.id)?'Reviewed ✓ · undo':'Mark as reviewed','button secondary','data-topic="'+t.id+'"')}${button('print','Print these notes','ghost')}</div><hr class="divider"><h3>A quick concept check</h3><p>${esc(t.mcq.q)}</p><div class="choices">${t.mcq.choices.map((c,i)=>button('concept',esc(c),'choice',`data-correct="${i===t.mcq.correct}" data-topic="${t.id}"`)).join('')}</div><div id="concept-feedback" class="feedback" role="status"></div></section><section class="panel"><div class="eyebrow">STEADY DOES IT</div><h3>Understanding takes a few visits.</h3><p>Reviewed means you have read it. Mastered questions count correct answers you reached before opening a solution.</p>${link('focus','Take a focus break ↗','text-link')}</section></aside></div>`;}
function practice(){const t=topic(route[1]),i=Math.max(0,Math.min(count(t)-1,Math.floor(Number(route[2])||0)));current=getQ(t.id,i);revealed=0;const q=current;return heading('WORKED PRACTICE',t.title,'Try it first. You can reveal one step whenever you need a hand.',link('topic/'+t.id,'← Topic notes','button secondary'))+`<div class="columns"><section class="panel"><div class="actions"><span class="pill">QUESTION ${i+1} / ${count(t)}</span><span class="pill">${q.skill}</span></div><div class="question">${esc(q.text)}</div>${q.type==='number'?`<form id="answer-form"><label>Your answer ${q.unit?'('+esc(q.unit)+')':''}<div class="answer-row"><input name="answer" required autocomplete="off" inputmode="decimal" placeholder="Your answer…"><button class="button" type="submit">Check answer</button></div></label><small>Use up to two decimal places. Decimal commas and points are accepted.</small></form>`:`<div class="choices">${q.choices.map((c,j)=>button('answer-choice',esc(c),'choice',`data-index="${j}"`)).join('')}</div>`}<div id="answer-feedback" class="feedback" aria-live="polite"></div><hr class="divider"><div class="actions no-print">${button('step','Unfold the first step','button','id="step-button"')}${button('solution','Show full solution')}${button('save-question','Save to notebook','ghost')}</div><div id="steps" aria-live="polite"></div><div class="actions no-print" style="margin-top:25px">${i>0?link('practice/'+t.id+'/'+(i-1),'← Previous','button secondary'):''}${i<count(t)-1?link('practice/'+t.id+'/'+(i+1),'Next question →'):link('learn','Choose a new topic ↗')}</div></section><aside><section class="panel no-print"><h3>Your working space</h3><label>Scratchpad<textarea id="scratch" placeholder="What do I know? What do I need?">${esc(state.notes['scratch:'+q.key]||'')}</textarea></label>${button('save-scratch','Save working','button secondary small','style="margin-top:12px"')}<p class="status-line">Saved on this device when you press Save.</p></section><section class="panel no-print"><h3>Choose a practice question</h3><label>Topic<select id="practice-topic">${topics.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.title}</option>`).join('')}</select></label><label style="margin-top:12px">Question number<input id="question-number" type="number" min="1" max="${count(t)}" value="${i+1}"></label><div class="actions" style="margin-top:14px">${button('jump-question','Go','button small')}${button('random-question','Surprise me','button secondary small')}</div><p class="status-line">${t.id==='ethics'?'Eight different ethical situations.':'75 variations across three question types. The numbers change as you move through the bank.'}</p></section></aside></div>`;}
function showSteps(all=false){if(!current)return;revealed=all?current.steps.length:Math.min(current.steps.length,revealed+1);$('#steps').innerHTML=current.steps.slice(0,revealed).map((s,i)=>`<div class="step"><span class="step-number">${i+1}</span><div>${esc(s)}</div></div>`).join('');$('#step-button').textContent=revealed===current.steps.length?'All steps unfolded ✓':'Unfold the next step';$('#step-button').disabled=revealed===current.steps.length;}
function recordAnswer(value){const ok=isCorrect(current,value),assisted=revealed>0;state.attempts.push({key:current.key,topic:current.topic,index:current.index,correct:ok,assisted,date:new Date().toISOString()});state.attempts=state.attempts.slice(-500);if(ok&&!assisted&&!state.mastered.includes(current.key))state.mastered.push(current.key);activity();save();const f=$('#answer-feedback');f.className='feedback'+(ok?'':' wrong');f.textContent=ok?(assisted?'That’s it. Now try a fresh version without the steps.':'You’ve got it! Your independent correct answer is saved.'):'A useful first try. Check the units and the calculation, or unfold a step.';}
function labs(){const tool=tools.find(t=>t.id===route[1]);if(!tool)return heading('TRY IT. MOVE IT. UNDERSTAND IT.',config.lab,'Change the figures, follow the working and see what happens.')+`<div class="grid">${tools.map(t=>`<a class="topic-card" href="#lab/${t.id}"><div class="topic-symbol">${icon('lab')}</div><h3>${t.title}</h3><p>${t.desc}</p><div class="card-bottom"><b>Open the calculator ↗</b></div></a>`).join('')}</div>`;return heading('INTERACTIVE LAB',tool.title,tool.desc,link('lab','← All lab tools','button secondary'))+`<div class="columns equal"><section class="panel"><form id="lab-form"><div class="form-grid">${tool.fields.map(f=>`<label class="${f.type==='text'?'wide':''}">${f.label}${f.options?`<select name="${f.name}">${f.options.map(([value,label])=>`<option value="${esc(value)}" ${f.value===value?'selected':''}>${esc(label)}</option>`).join('')}</select>`:`<input name="${f.name}" type="${f.type||'number'}" value="${esc(f.value)}" ${f.type==='text'?'':`min="${f.min??0}" max="1000000000" step="any"`} required>`}</label>`).join('')}</div><button class="button" type="submit" style="margin-top:23px">Calculate & explain ↗</button></form><p class="status-line">Learning model · uses the values you enter.</p></section><section class="panel" id="lab-result" aria-live="polite"></section></div>`;}
function runLab(){const form=$('#lab-form');if(!form)return;const tool=tools.find(t=>t.id===route[1]),v=Object.fromEntries(new FormData(form));tool.fields.forEach(f=>{if(!f.options&&f.type!=='text')v[f.name]=Number(v[f.name]);});try{const r=calculate(tool.id,v);$('#lab-result').innerHTML=`<div class="eyebrow">THE NUMBERS, UNPACKED</div><div class="tool-result">${esc(r.value)}<small>${esc(r.label)}</small></div>${r.lines.map((s,i)=>`<div class="step"><span class="step-number">${i+1}</span><div>${esc(s)}</div></div>`).join('')}${r.chart?`<div class="chart-bars" aria-label="Comparison of calculated amounts">${r.chart.map(([label,value])=>`<div class="chart-bar" style="height:${Math.max(3,value/Math.max(1,...r.chart.map(x=>x[1]))*85)}%"><span>${fmt(round(value))}</span><small>${esc(label)}</small></div>`).join('')}</div>`:''}`;}catch(e){$('#lab-result').innerHTML=`<div class="callout warm">${esc(e.message)}</div>`;}}
function revision(){const list=topics.filter(t=>!flashFilter||t.id===flashFilter),deck=list.flatMap(t=>[{front:t.title+' · the key idea',back:t.summary},{front:t.title+' · the formula',back:t.formula},{front:t.title+' · the memory nudge',back:t.memory}]);flash=Math.max(0,Math.min(deck.length-1,flash));const c=deck[flash];return heading('REVISION TOOLKIT','A little recall goes a long way.','Try remembering before you flip. No rush, no score.')+`<div class="columns"><section class="panel no-print"><label>Flashcard topic<select id="flash-topic"><option value="">All topics</option>${topics.map(t=>`<option value="${t.id}" ${flashFilter===t.id?'selected':''}>${t.title}</option>`).join('')}</select></label><p class="status-line">Card ${flash+1} of ${deck.length}</p><button class="flashcard" data-action="flip"><small>${flipped?'THE OTHER SIDE':'TAP TO REVEAL'}</small>${esc(flipped?c.back:c.front)}</button><div class="actions">${button('flash-prev','← Previous')}${button('flip',flipped?'Show prompt':'Flip card','button')}${button('flash-next','Next →')}</div></section><section class="panel"><h3>A formula worth keeping</h3><p>Use the formula list as a quick reference, then test yourself with the cards.</p><label class="no-print">Jump to a formula<select id="formula-topic">${topics.map(t=>`<option value="${t.id}">${t.title}</option>`).join('')}</select></label><div class="formula" id="formula-display">${esc(topics[0].formula)}</div>${button('print','Print formula sheet','button secondary small','data-sheet="formulas"')}</section></div>`;}
function planner(){const completed=state.tasks.filter(t=>t.done).length;return heading('MY STUDY PLAN','A plan with room to breathe.','Give the next small step a date. Leave space for real life.')+`<div class="columns"><section><div class="panel"><form id="task-form" class="form-grid"><label class="wide">One doable task<input name="text" required maxlength="180" placeholder="e.g. Two FIFO questions, then a tea break"></label><label>Study date<input name="date" type="date" value="${nowDate()}" required></label><label>Topic<select name="topic"><option value="">General revision</option>${topics.map(t=>`<option value="${t.id}">${t.title}</option>`).join('')}</select></label><div class="wide actions"><button class="button" type="submit">Add my next step</button>${button('starter-plan','Make a 7-day starter plan')}</div></form></div><div class="section-head"><h2>My next little steps</h2><span class="pill">${completed} / ${state.tasks.length} DONE</span></div>${state.tasks.length?state.tasks.slice().sort((a,b)=>String(a.date).localeCompare(String(b.date))).map(t=>`<div class="task ${t.done?'done':''}"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''} aria-label="Mark ${esc(t.text)} as done"><label>${esc(t.text)}<small style="display:block">${esc(t.date)} · ${esc(topics.find(x=>x.id===t.topic)?.title||'General revision')}</small></label>${button('calendar-task','↓','icon-button',`data-id="${esc(t.id)}" aria-label="Download calendar event"`)}${button('delete-task','×','icon-button',`data-id="${esc(t.id)}" aria-label="Delete task"`)}</div>`).join(''):`<div class="empty"><h3>Your plan starts with one small thing.</h3><p>Add a task above, or try the seven-day starter plan.</p></div>`}</section><aside><section class="panel"><h3>Try a gentle study rhythm</h3><p>25 minutes on one idea.<br>5 minutes away from the screen.<br>One question from yesterday.<br>One sentence about what clicked.</p>${link('focus','Open the focus timer ↗','button secondary')}</section><section class="panel"><h3>A date is an invitation.</h3><p>You can change course. A missed day doesn’t cancel the work you’ve already done.</p>${button('export','Download my progress backup','button secondary small')}</section></aside></div>`;}
function notebook(){const notes=Object.entries(state.notes).filter(([k,v])=>String(v).trim()&&!k.startsWith('scratch:')),misses=[...new Map(state.attempts.filter(x=>!x.correct&&!state.mastered.includes(x.key)).map(x=>[x.key,x])).values()].reverse();return heading('MY NOTEBOOK','Keep the little lightbulb moments.','Notes, saved questions and the bits you want to revisit.',button('export','Back up my work'))+`<div class="columns"><section><div class="panel"><h2>My notes</h2>${notes.length?notes.map(([id,text])=>`<div class="list-row"><div><a class="text-link" href="#topic/${esc(topics.some(t=>t.id===id)?id:topics[0].id)}">${esc(topics.find(t=>t.id===id)?.title||id)} ↗</a><p class="note-text">${esc(String(text).slice(0,20000))}</p></div>${button('delete-note','×','icon-button',`data-id="${esc(id)}" aria-label="Delete note"`)}</div>`).join(''):'<p class="muted">Save a note inside any topic. It will be waiting here.</p>'}</div><div class="panel"><h2>My saved topics & questions</h2>${state.bookmarks.length?state.bookmarks.map(id=>{const[t,i]=String(id).split(':');return`<div class="list-row">${link(i!==undefined?'practice/'+t+'/'+i:'topic/'+t,esc(topic(t).title)+(i!==undefined?' · Q'+(Number(i)+1):'')+' ↗','text-link')}${button('remove-bookmark','×','icon-button',`data-id="${esc(id)}" aria-label="Remove bookmark"`)}</div>`;}).join(''):'<p class="muted">Save a topic or question while studying.</p>'}</div></section><aside><section class="panel"><h3>The “let’s try again” pile</h3><p>Questions you missed, until you answer them independently.</p>${misses.slice(0,20).map(m=>`<a class="resource-link" href="#practice/${esc(m.topic)}/${m.index}">${esc(topic(m.topic).title)} · Q${Number(m.index)+1} ↗</a>`).join('')||'<small>No questions waiting here. Your next try is a fresh start.</small>'}</section><section class="panel"><h3>Device storage</h3><p>Your work is stored in this browser on this device. Clearing browser data removes it. Export a backup to move it to another device.</p><div class="actions">${button('export','Export backup','button small')}${button('import','Restore backup','button secondary small')}</div><input id="import-file" type="file" accept="application/json,.json" hidden><p class="status-line">${storageOK?'Storage is available.':'Storage is unavailable. Export your work before closing.'}</p></section></aside></div>`;}
function progress(){const total=topics.reduce((s,t)=>s+count(t),0),acc=state.attempts.length?Math.round(state.attempts.filter(a=>a.correct).length/state.attempts.length*100):0;return heading('MY PROGRESS','Look at the ground you’ve covered.','Every independent correct answer counts once. Review and practice are different kinds of progress.')+`<div class="stats">${stat('check',state.mastered.length+'/'+total,'questions mastered')}${stat('book',state.reviewed.length+'/'+topics.length,'topics reviewed')}${stat('chart',acc+'%','recent practice accuracy')}${stat('star',state.days.length,'active study days')}</div><div class="columns"><section class="panel"><h2>Your topic trail</h2>${topics.map(t=>{const got=state.mastered.filter(k=>k.startsWith(t.id+':')).length;return`<div class="list-row"><div style="flex:1"><a class="text-link" href="#topic/${t.id}">${t.title} ↗</a><div class="progress-track"><span style="width:${got/count(t)*100}%"></span></div><small>${got} / ${count(t)} independently correct · ${state.reviewed.includes(t.id)?'notes reviewed':'notes waiting'}</small></div></div>`;}).join('')}</section><aside><section class="panel"><h3>Your mini-mock results</h3>${state.exams.length?state.exams.slice().reverse().slice(0,10).map(e=>`<a class="resource-link" href="#result/${esc(e.id)}"><b>${e.score} / ${e.questions.length}</b> · ${new Date(e.date).toLocaleDateString('en-ZA')}<small>Open question review ↗</small></a>`).join(''):'<p>No mini mocks yet. A short practice round can help you find your next topic.</p>'}${link('exam','Try a mini mock ↗','button secondary small')}</section><section class="panel"><h3>Milestones</h3><span class="badge">${state.attempts.length?'✓':'○'} First attempt</span><span class="badge">${state.mastered.length>=10?'✓':'○'} Ten small wins</span><span class="badge">${state.reviewed.length>=3?'✓':'○'} Three topics explored</span><span class="badge">${state.exams.length?'✓':'○'} First mini mock</span><p class="status-line">Accuracy uses up to the latest 500 practice attempts. Mini-mock results are kept separately.</p></section></aside></div>`;}
function exam(){const e=state.activeExam;if(e){const i=Math.max(0,Math.min(e.questions.length-1,Number(route[1])||0)),ref=e.questions[i],q=getQ(ref.topic,ref.index),value=e.answers[i]??'';return heading('MINI MOCK · '+(i+1)+' OF '+e.questions.length,'One question at a time.','Answers are marked when you submit the whole mini mock.',`<span class="pill" id="exam-clock"></span>`)+`<div class="columns"><section class="panel"><span class="pill">${topic(q.topic).title}</span><div class="question">${esc(q.text)}</div><form id="exam-answer" data-index="${i}">${q.type==='number'?`<label>Your answer (${esc(q.unit||'number')})<input name="answer" value="${esc(value)}" inputmode="decimal" autocomplete="off"></label>`:`<div class="choices">${q.choices.map((c,j)=>`<label class="choice ${String(j)===String(value)?'selected':''}"><input type="radio" name="answer" value="${j}" ${String(j)===String(value)?'checked':''}> ${esc(c)}</label>`).join('')}</div>`}<div class="actions" style="margin-top:24px"><button class="button" type="submit">${i<e.questions.length-1?'Save & next →':'Save answer'}</button>${i>0?link('exam/'+(i-1),'← Previous','button secondary'):''}</div></form></section><aside class="panel"><h3>Your question trail</h3><div class="actions">${e.questions.map((q,j)=>link('exam/'+j,`${j+1}${e.answers[j]!==undefined&&e.answers[j]!==''?' ✓':''}`,'button '+(i===j?'':'secondary ')+'small')).join('')}</div><hr class="divider"><p>${e.answers.filter(x=>x!==undefined&&x!=='').length} / ${e.questions.length} answers saved. Save the current answer before moving with the question trail.</p>${button('finish-exam','Submit mini mock','button')}<p class="status-line">Timer continues if you leave or reload the page. Unanswered questions score zero.</p></aside></div>`;}
 return heading('THE PRACTICE ROOM','A mini mock. A clearer next step.','Short checks with one mark per answer. These are original practice rounds, not full 150-mark examination papers.')+`<div class="columns equal"><section class="panel"><h2>Make a practice round</h2><form id="exam-start"><label>Topic group<select name="paper"><option value="all">All topics</option><option value="1">Paper 1 · ${config.paper1}</option><option value="2">Paper 2 · ${config.paper2}</option></select></label><div class="form-grid" style="margin-top:16px"><label>Questions<select name="questions"><option value="10">10 questions</option><option value="20">20 questions</option></select></label><label>Time allowance<select name="minutes"><option value="20">20 minutes</option><option value="40">40 minutes</option><option value="60">60 minutes</option></select></label></div><button class="button" type="submit" style="margin-top:22px">Start my mini mock ↗</button></form></section><section class="panel"><h3>Before you begin</h3><p>Bring a calculator, some paper and room for messy working. Numeric answers use a tolerance of one cent or 0.01 units. Method marks are not assessed in this short format.</p><p>After submission, see each answer, the working and links back to the lesson.</p><div class="callout">For full exam practice: ${link('papers','open official papers & memos ↗','text-link')}</div></section></div>`;}
function finishExam(){const e=state.activeExam;if(!e)return;let score=0;e.questions.forEach((ref,i)=>{if(isCorrect(getQ(ref.topic,ref.index),e.answers[i]??''))score++;});e.score=score;e.date=new Date().toISOString();state.exams.push(e);state.exams=state.exams.slice(-20);state.activeExam=null;activity();save();location.hash='result/'+e.id;}
function resultPage(){const e=state.exams.find(e=>e.id===route[1]);if(!e)return heading('RESULTS','No result found.','Choose a saved result from My progress.',link('progress','My progress'));return heading('MINI-MOCK REVIEW',`${e.score} out of ${e.questions.length}. A useful next step.`,`Submitted ${new Date(e.date).toLocaleString('en-ZA')}. Open each question to compare your answer with the worked solution.`,link('exam','Another round ↗'))+`<section class="panel">${e.questions.map((ref,i)=>{const q=getQ(ref.topic,ref.index),ok=isCorrect(q,e.answers[i]??''),answer=q.type==='choice'?q.choices[q.answer]:fmt(q.answer)+' '+q.unit,entered=e.answers[i]===null||e.answers[i]===undefined||String(e.answers[i]).trim()===''?'Not answered':q.type==='choice'?q.choices[Number(e.answers[i])]||'Not answered':e.answers[i];return`<details style="padding:15px 0;border-bottom:1px solid var(--line)"><summary><b>${ok?'✓':'○'} Question ${i+1}</b> · ${topic(q.topic).title} · ${ok?'Correct':'Revisit'}</summary><div class="question">${esc(q.text)}</div><p>Your answer: ${esc(entered)}</p><div class="callout">Correct answer: ${esc(answer)}</div>${q.steps.map((s,i)=>`<div class="step"><span class="step-number">${i+1}</span>${esc(s)}</div>`).join('')}${link('topic/'+q.topic,'Return to the lesson ↗','text-link')}</details>`;}).join('')}</section>`;}
function papers(){const collections=[['2025 November','https://www.education.gov.za/Curriculum/NationalSeniorCertificate%28NSC%29Examinations/2025NovemberExamPapers.aspx'],['2025 May/June','https://www.education.gov.za/LinkClick.aspx?link=5475&mid=4149&portalid=0&tabid=338'],['2024 May/June','https://www.education.gov.za/Curriculum/NationalSeniorCertificate%28NSC%29Examinations/2024MayJuneExampapers.aspx'],['2023 May/June','https://www.education.gov.za/Curriculum/NationalSeniorCertificate%28NSC%29Examinations/2023MayJuneExamPapers.aspx'],['2022 May/June','https://www.education.gov.za/Curriculum/NationalSeniorCertificate%28NSC%29Examinations/2022MayJuneExamPapers.aspx'],['2021 November','https://www.education.gov.za/Curriculum/NationalSeniorCertificate%28NSC%29Examinations/2021NSCExamPapers/tabid/2922/ItemId/27498/Default.aspx']];return heading('OFFICIAL PAST PAPERS','The real paper. Your own pace.','Open a DBE collection, find '+(config.subject==='maths-literacy'?'Mathematical Literacy':'Accounting')+', then choose the paper, memo and supporting documents in your language.')+`<div class="grid">${collections.map(([year,url])=>`<a class="topic-card" href="${url}" target="_blank" rel="noopener"><div class="topic-symbol">${icon('paper')}</div><div class="eyebrow">DBE · NATIONAL COLLECTION</div><h3>${year}</h3><p>Find Paper 1, Paper 2 and memoranda.${config.subject==='maths-literacy'?' Check for an addendum.':' Download the answer book too.'}</p><div class="card-bottom"><b>Open official collection ↗</b></div></a>`).join('')}</div><div class="columns" style="margin-top:24px"><section class="panel"><h3>Try the three-pass method</h3><p>1. Try a section under time.<br>2. Mark using the official memo.<br>3. Redo missed questions without looking.</p><p>${config.subject==='maths-literacy'?'Both papers are 150 marks with a three-hour duration in the DBE guidance.':'Both papers are 150 marks with a two-hour duration in the DBE guidance.'} Read the instructions printed on the paper you open.</p></section><section class="panel"><h3>A word about these links</h3><p>These open DBE collection pages, rather than individual PDF downloads. Official papers and memos retain their original credits. Internet access is needed for external resources.</p><a class="text-link" target="_blank" rel="noopener" href="https://www.education.gov.za/2021Grade12ExamGuidelines.aspx">DBE examination guidelines ↗</a></section></div>`;}
function videos(){const selected=topics.find(t=>t.id===route[1]),list=selected?[selected]:topics;return heading('VIDEO LESSON FINDER','Find the explanation that clicks.','Topic-specific YouTube searches open in a new tab. Check the lesson’s grade, topic and method before following along.')+`<div class="grid">${list.map(t=>`<a class="topic-card" href="https://www.youtube.com/results?search_query=${encodeURIComponent('South Africa Grade 12 '+config.label+' '+t.title.replace(/[^À-ɏA-Za-z0-9 ]/g,' '))}" target="_blank" rel="noopener"><div class="topic-symbol">${icon('play')}</div><h3>${t.title}</h3><p>Find explanations and worked video examples. Pause, try the step, then continue.</p><div class="card-bottom"><b>Search YouTube lessons ↗</b></div></a>`).join('')}</div>${config.subject==='maths-literacy'?`<section class="panel" style="margin-top:22px"><h3>Finance, data & probability revision</h3><p>SmartPrep MathsScience · External video lesson. Published June 2026. The creator’s examples and rates apply to their stated context.</p><a class="button secondary" href="https://www.youtube.com/watch?v=4JXetM65Dnc" target="_blank" rel="noopener">Watch the lesson on YouTube ↗</a></section>`:''}<p class="status-line">Video creators retain their credits. Search results and availability can change.</p>`;}
function buddy(){const t=topic(route[1]);return heading('ASK '+config.buddy.toUpperCase(),'Let’s untangle that little knot.','A guided study helper built from the notes and question bank. Pick a topic and the kind of help you need.')+`<div class="columns"><section class="panel"><form id="buddy-form"><label>What are we working on?<select name="topic">${topics.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.title}</option>`).join('')}</select></label><label style="margin-top:17px">What would help?<select name="help"><option value="idea">Explain the idea simply</option><option value="formula">Show the formula and a worked example</option><option value="trap">Help me avoid the usual mistake</option><option value="memory">Give me a memory nudge</option><option value="plan">Give me a tiny study plan</option></select></label><button class="button" type="submit" style="margin-top:22px">Ask ${config.buddy} ↗</button></form><div id="buddy-answer" aria-live="polite"></div></section><aside class="panel"><h3>Questions are welcome here.</h3><p>This helper looks up prepared explanations and worked examples. For a new question from your school paper, bring the full question and your working to your tutor.</p><div class="callout">“I don’t understand yet” is a useful place to begin.</div>${link('focus','Take a slow breath ↗','text-link')}</aside></div>`;}
function focus(){return heading('THE QUIETER CORNER','A little focus. A little breathing room.','Choose one small task. Keep breaks away from the screen when you can.')+`<div class="columns equal"><section class="panel" style="text-align:center"><div class="eyebrow">YOUR FOCUS TIMER</div><div class="timer-number" id="focus-clock">${clock(timerRemaining)}</div><div class="actions" style="justify-content:center">${button('timer-toggle',timerRunning?'Pause':'Start','button','id="timer-toggle"')}${button('timer-reset','Reset')}</div><div class="tabs" style="justify-content:center;margin-top:22px">${button('timer-mode','25-minute focus','','data-minutes="25"')}${button('timer-mode','5-minute break','','data-minutes="5"')}${button('timer-mode','15-minute reset','','data-minutes="15"')}</div><p class="status-line">The timer keeps running while this app is open. Background tabs may delay the visible update.</p></section><section class="panel" style="text-align:center"><div class="eyebrow">A MOMENT TO LAND</div><div class="breath-circle">Breathe gently</div><p>Relax your shoulders. Breathe at a comfortable pace. Look away from the screen for a moment.</p>${button('focus-toggle','Toggle focus layout','button secondary small')}</section></div>`;}
function educator(){return heading('EDUCATOR STUDIO','A few useful things for your lesson.','Create printable practice and keep a set of resource links on this device.')+`<div class="columns"><section><div class="panel"><h2>Make a practice worksheet</h2><form id="worksheet-form" class="form-grid"><label>Topic<select name="topic">${topics.map(t=>`<option value="${t.id}">${t.title}</option>`).join('')}</select></label><label>Number of questions<select name="amount"><option value="5">5 questions</option><option value="8">8 questions</option></select></label><label class="wide"><span><input name="memo" type="checkbox"> Include worked memo after the questions</span></label><button class="button" type="submit">Prepare printable worksheet</button></form></div><div class="panel"><h2>My resource shelf</h2><form id="resource-form" class="form-grid"><label>Resource title<input name="title" required maxlength="100" placeholder="e.g. This week’s class notes"></label><label>Public resource link<input name="url" required type="url" placeholder="https://…"></label><button class="button" type="submit">Save resource link</button></form>${state.resources.map((r,i)=>`<div class="list-row"><a class="text-link" href="${esc(safeURL(r.url)||'#')}" target="_blank" rel="noopener">${esc(r.title)} ↗</a>${button('delete-resource','×','icon-button',`data-index="${i}" aria-label="Delete resource"`)}</div>`).join('')}</div></section><aside><section class="panel"><h3>Share with your learners</h3><p>This app opens without a login. Send the app link to your class, then direct learners to a topic, question or lab.</p>${button('copy-link','Copy this app’s link','button secondary')}<p class="status-line">Resources saved here stay on this device. To share a resource with your class, send its original link.</p></section><section class="panel"><h3>Print or save as PDF</h3><p>Prepare a worksheet, then use the print button. Your browser can print it or save a PDF. Solutions start after the question pages when included.</p>${link('papers','Use official answer books too ↗','text-link')}</section></aside></div>`;}
function about(){return heading('ABOUT THIS LITTLE STUDIO',config.tagline,'Created for learners who deserve clear explanations, patient practice and a place to begin.')+`<div class="columns"><section class="panel"><h2>${config.name}</h2><p>Created by <b>Simoné Govender</b> · Bachelor of Education · Web developer.</p><p>A Grade 12 ${config.label.toLowerCase()} study companion for South African learners, inspired by the small-step approach of Plot Twist.</p><h3>How the practice works</h3><p>Calculation topics each have 75 numerical variations across three question types. Accounting ethics has eight distinct scenarios. Original practice supports revision; it does not reproduce official papers or replace the full curriculum.</p><h3>Your privacy & saved work</h3><p>No account is required. Your name, notes, answers, planner and preferences are saved in this browser’s local storage. They do not sync between devices. Export a backup before clearing browser data.</p><p>The apps do not add analytics or collect your study records on a server. GitHub Pages and external font, video and resource services handle requests under their own policies. External resources require internet access.</p><h3>Offline study</h3><p>After a successful first online load, the core app is cached where your browser supports service workers. Topic notes, practice and calculators can then work offline. External videos, fonts and official resources still need internet access.</p><div id="offline-status" class="status-line">Checking offline availability…</div></section><aside class="panel"><h3>Sources & learning companions</h3><a class="resource-link" href="https://www.education.gov.za/2021Grade12ExamGuidelines.aspx" target="_blank" rel="noopener">DBE Grade 12 examination guidelines ↗</a><a class="resource-link" href="https://www.education.gov.za/Curriculum/NationalCurriculumStatementsGradesR-12.aspx" target="_blank" rel="noopener">DBE curriculum & CAPS ↗</a><a class="resource-link" href="../plot-twist/">Plot Twist · Mathematics ↗</a><a class="resource-link" href="../quantum-jump/">Quantum Jump · Physical Sciences ↗</a><a class="resource-link" href="../${config.other}/">${config.otherName} ↗</a><a class="resource-link" href="https://cosmicbubblegumgirl.github.io/simone-cosmic-portfolio/" target="_blank" rel="noopener">Simoné’s portfolio ↗</a><h3 style="margin-top:24px">Have your say</h3><p>If a worked answer needs a second look, share the topic and question number with your tutor so it can be checked.</p></aside></div>`;}
function settings(){modal(`<div class="eyebrow">MAKE YOURSELF COMFORTABLE</div><h2 style="margin:12px 0 23px">A little room for your brain.</h2><div class="settings">${[['dark','Dark mode'],['contrast','Higher contrast'],['motion','Reduce motion'],['warm','Warmer screen colours'],['focus','Focus layout']].map(([id,label])=>`<label><input type="checkbox" data-pref="${id}" ${state.prefs[id]?'checked':''}>${label}</label>`).join('')}<label>Text size<select data-pref="font"><option value="1" ${Number(state.prefs.font||1)===1?'selected':''}>Standard</option><option value="1.1" ${Number(state.prefs.font)===1.1?'selected':''}>Larger</option><option value="1.25" ${Number(state.prefs.font)===1.25?'selected':''}>Largest</option></select></label></div><p class="status-line">Preferences are saved on this device.</p>`);}
function clock(seconds){seconds=Math.max(0,seconds);return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
function render(){if(lastQuizView&&$('#exam-answer'))saveExamAnswer();route=location.hash.slice(1).split('/').map(decodeURIComponent);lastQuizView=false;document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');current=null;const name=route[0]||'home',views={home,learn,topic:topicPage,practice,lab:labs,revision,planner,notebook,progress,exam,result:resultPage,papers,videos,buddy,focus,educator,about};try{main.innerHTML=(views[name]||home)();}catch(e){main.innerHTML=heading('LET’S RESET THAT STEP','This page needs another try.','Your saved work is still here.',link('home','Back to my starting point'));}$$('nav a').forEach(a=>{const active=a.dataset.nav===name||(['topic','practice'].includes(name)&&a.dataset.nav==='learn')||name==='result'&&a.dataset.nav==='exam';a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});$('#profile-button').textContent=state.name==='Curious mind'?'My space':state.name;document.title=config.name+' · '+({learn:'Learn & practise',lab:config.lab,exam:'Mini mock',home:config.tagline}[name]||name.charAt(0).toUpperCase()+name.slice(1));if($('#lab-form'))runLab();if(name==='about')offlineStatus();lastQuizView=name==='exam'&&!!state.activeExam;main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});tick();}
function saveExamAnswer(){const form=$('#exam-answer');if(!form||!state.activeExam)return;const data=new FormData(form);state.activeExam.answers[Number(form.dataset.index)]=data.get('answer')??'';save();}
function tick(){if(timerRunning){timerRemaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));if(timerRemaining===0){timerRunning=false;toast('Focus round complete. Stretch, look away, take a break.');if($('#timer-toggle'))$('#timer-toggle').textContent='Start';}}if($('#focus-clock'))$('#focus-clock').textContent=clock(timerRemaining);const e=state.activeExam;if(e){const remaining=Math.max(0,Math.ceil((e.ends-Date.now())/1000));if($('#exam-clock'))$('#exam-clock').textContent=clock(remaining)+' left';if(!remaining){saveExamAnswer();finishExam();toast('Time is up. Your saved answers have been marked.');}}}
document.addEventListener('click',async e=>{const a=e.target.closest('[data-action]');if(!a)return;const act=a.dataset.action;
 if(act==='menu'){document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',document.body.classList.contains('menu-open'));return;}
 if(act==='theme'){state.prefs.dark=!state.prefs.dark;prefs();return;}
 if(act==='settings'){settings();return;}
 if(act==='close'){close();return;}
 if(act==='profile'){modal(`<h2>Make yourself at home.</h2><form id="profile-form"><label>What should we call you?<input name="name" value="${esc(state.name)}" maxlength="40" required></label><button type="submit" class="button" style="margin-top:18px">Save my name</button></form><p class="status-line">This is a local profile, saved on this device. No login required.</p>`);return;}
 if(act==='focus-toggle'){state.prefs.focus=!state.prefs.focus;prefs();return;}
 if(act==='print'){if(a.dataset.sheet==='formulas'){modal(`<h2>Formula sheet</h2><p>${config.name} · Simoné Govender</p>${topics.map(t=>`<h3>${t.title}</h3><div class="formula">${esc(t.formula)}</div>`).join('')}${button('print-modal','Print / save PDF','button no-print')}`);}else window.print();return;}
 if(act==='print-modal'){const content=$('#modal-content').innerHTML;close();main.innerHTML=content;window.print();render();return;}
 if(act==='concept'){const t=topic(a.dataset.topic);$('#concept-feedback').textContent=(a.dataset.correct==='true'?'That’s it! ':'Let’s look again. ')+t.mcq.why;return;}
 if(act==='step'){showSteps();return;}if(act==='solution'){showSteps(true);return;}
 if(act==='answer-choice'){if(current){$$('.choice',main).forEach(x=>x.classList.remove('selected'));a.classList.add('selected');recordAnswer(Number(a.dataset.index));}return;}
 if(act==='save-scratch'){state.notes['scratch:'+current.key]=$('#scratch').value;save();toast('Working saved.');return;}
 if(act==='save-question'){if(!state.bookmarks.includes(current.key))state.bookmarks.push(current.key);save();toast('Question tucked into your notebook.');return;}
 if(act==='bookmark-topic'){const id=a.dataset.topic;if(state.bookmarks.includes(id))state.bookmarks=state.bookmarks.filter(x=>x!==id);else state.bookmarks.push(id);save();a.textContent=state.bookmarks.includes(id)?'Saved ✓':'Save topic';return;}
 if(act==='review'){const id=a.dataset.topic;if(state.reviewed.includes(id))state.reviewed=state.reviewed.filter(x=>x!==id);else state.reviewed.push(id);activity();save();a.textContent=state.reviewed.includes(id)?'Reviewed ✓ · undo':'Mark as reviewed';return;}
 if(act==='jump-question'){const t=topic($('#practice-topic').value);location.hash='practice/'+t.id+'/'+Math.max(0,Math.min(count(t)-1,Number($('#question-number').value)-1||0));return;}
 if(act==='random-question'){const t=topic($('#practice-topic').value);location.hash='practice/'+t.id+'/'+Math.floor(Math.random()*count(t));return;}
 if(['flip','flash-prev','flash-next'].includes(act)){if(act==='flip')flipped=!flipped;else{flipped=false;const size=(flashFilter?1:topics.length)*3;flash=(flash+(act==='flash-next'?1:-1)+size)%size;}render();return;}
 if(act==='delete-task'){state.tasks=state.tasks.filter(t=>t.id!==a.dataset.id);save();render();return;}
 if(act==='calendar-task'){const t=state.tasks.find(t=>t.id===a.dataset.id);if(!t)return;const d=t.date.replaceAll('-',''),next=new Date(t.date+'T12:00:00Z');next.setUTCDate(next.getUTCDate()+1);const end=next.toISOString().slice(0,10).replaceAll('-',''),escapeICS=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');download(config.id+'-study-task.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//'+config.name+'//Study Plan//EN','BEGIN:VEVENT','UID:'+t.id+'@'+config.id+'.study','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z'),'DTSTART;VALUE=DATE:'+d,'DTEND;VALUE=DATE:'+end,'SUMMARY:'+escapeICS(t.text),'DESCRIPTION:'+config.name+' study session','END:VEVENT','END:VCALENDAR'].join('\r\n')+'\r\n','text/calendar');return;}
 if(act==='starter-plan'){if(state.tasks.some(t=>t.starter)){toast('Your starter plan is already on the list.');return;}for(let i=0;i<7;i++){const date=new Date();date.setDate(date.getDate()+i);const d=new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit'}).format(date),t=topics[i%topics.length];state.tasks.push({id:crypto.randomUUID(),text:'Read '+t.title+' & try two questions',date:d,topic:t.id,done:false,starter:true});}save();render();return;}
 if(act==='delete-note'){delete state.notes[a.dataset.id];save();render();return;}
 if(act==='remove-bookmark'){state.bookmarks=state.bookmarks.filter(x=>x!==a.dataset.id);save();render();return;}
 if(act==='export'){download(config.id+'-backup-'+nowDate()+'.json',JSON.stringify({app:config.id,exported:new Date().toISOString(),data:state},null,2));toast('Your backup is ready to keep.');return;}
 if(act==='import'){if(!$('#import-file')){modal(`<h2>Restore your saved work</h2><p>Choose a ${config.name} backup. Restoring replaces this device’s current study records.</p><input id="import-file" type="file" accept="application/json,.json">`);}else $('#import-file').click();return;}
 if(act==='restore'){state=validate(pendingImport);pendingImport=null;save();prefs();close();render();toast('Backup restored.');return;}
 if(act==='finish-exam'){saveExamAnswer();const n=state.activeExam?.answers.filter(x=>x!==undefined&&x!=='').length||0;modal(`<h2>Ready to hand it in?</h2><p>${n} of ${state.activeExam.questions.length} questions have an answer. Once submitted, you can review every solution.</p><div class="actions">${button('confirm-exam','Submit & mark','button')}${button('close','Keep working')}</div>`);return;}
 if(act==='confirm-exam'){close();finishExam();return;}
 if(act==='timer-toggle'){if(timerRunning){timerRemaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));timerRunning=false;}else{if(!timerRemaining)timerRemaining=1500;timerEnd=Date.now()+timerRemaining*1000;timerRunning=true;}if($('#timer-toggle'))$('#timer-toggle').textContent=timerRunning?'Pause':'Start';tick();return;}
 if(act==='timer-reset'){timerRunning=false;timerRemaining=1500;render();return;}
 if(act==='timer-mode'){timerRunning=false;timerRemaining=Number(a.dataset.minutes)*60;render();return;}
 if(act==='delete-resource'){state.resources.splice(Number(a.dataset.index),1);save();render();return;}
 if(act==='copy-link'){const u=location.href.split('#')[0];try{await navigator.clipboard.writeText(u);toast('App link copied.');}catch{modal(`<h2>Your app link</h2><input readonly value="${esc(u)}" aria-label="App link">`);}return;}
 if(act==='speak'){if(!('speechSynthesis'in window)){toast('Read-aloud is unavailable in this browser.');return;}speechSynthesis.cancel();const t=topic(a.dataset.topic),u=new SpeechSynthesisUtterance([t.title,t.summary,...t.lessons.flat()].join('. '));u.lang='en-ZA';u.rate=.9;speechSynthesis.speak(u);return;}
 if(act==='stop-speech'){window.speechSynthesis?.cancel();return;}
});
let pendingImport=null;
document.addEventListener('submit',e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));
 if(f.id==='answer-form'){recordAnswer(d.answer);return;}
 if(f.id==='lab-form'){runLab();return;}
 if(f.id==='profile-form'){state.name=d.name.trim().slice(0,40)||'Curious mind';save();close();render();return;}
 if(f.id==='note-form'){state.notes[topic(route[1]).id]=d.text;activity();save();toast('Aha saved.');return;}
 if(f.id==='task-form'){state.tasks.push({id:crypto.randomUUID(),text:d.text.trim(),date:d.date,topic:d.topic,done:false});save();render();return;}
 if(f.id==='resource-form'){const url=safeURL(d.url);if(!url){toast('Use a full http or https link.');return;}state.resources.push({title:d.title.trim(),url});save();render();return;}
 if(f.id==='buddy-form'){const t=topic(d.topic),q=getQ(t.id,0);let html='';if(d.help==='idea')html=`<p>${esc(t.summary)}</p><h3>${esc(t.lessons[0][0])}</h3><p>${esc(t.lessons[0][1])}</p>`;if(d.help==='formula')html=`<div class="formula">${esc(t.formula)}</div><p>${esc(q.text)}</p>${q.steps.map(s=>`<p>${esc(s)}</p>`).join('')}`;if(d.help==='trap')html=`<div class="callout warm">${esc(t.trap)}</div>`;if(d.help==='memory')html=`<div class="callout">${esc(t.memory)}</div>`;if(d.help==='plan')html='<p>1. Read the key idea for three minutes.<br>2. Try question one with no solution open.<br>3. Compare your steps.<br>4. Try a fresh version.<br>5. Write one thing you now understand.</p>';$('#buddy-answer').innerHTML=`<hr class="divider"><div class="eyebrow">${config.buddy.toUpperCase()} · ${t.title}</div><div style="margin-top:18px">${html}</div><div class="actions">${link('topic/'+t.id,'Read the lesson','button secondary small')}${link('practice/'+t.id+'/0','Try a question','button small')}</div>`;return;}
 if(f.id==='exam-start'){const pool=topics.filter(t=>d.paper==='all'||!t.paper||t.paper===Number(d.paper)).flatMap(t=>Array.from({length:count(t)},(_,index)=>({topic:t.id,index})));for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}const amount=Number(d.questions);state.activeExam={id:crypto.randomUUID(),questions:pool.slice(0,amount),answers:Array(amount).fill(''),ends:Date.now()+Number(d.minutes)*60000,paper:d.paper};save();location.hash='exam/0';return;}
 if(f.id==='exam-answer'){saveExamAnswer();const i=Number(f.dataset.index);if(i<state.activeExam.questions.length-1)location.hash='exam/'+(i+1);else{toast('Answer saved. Submit when ready.');render();}return;}
 if(f.id==='worksheet-form'){const t=topic(d.topic),amount=Number(d.amount),chosen=new Set();while(chosen.size<Math.min(amount,count(t)))chosen.add(Math.floor(Math.random()*count(t)));const qs=[...chosen].map(i=>getQ(t.id,i));main.innerHTML=heading('PRACTICE WORKSHEET',t.title,`${config.name} · Compiled by Simoné Govender · Bachelor of Education`,button('print','Print / save as PDF'))+`<p>Name: _________________________ Date: __________________</p>${qs.map((q,i)=>`<section class="worksheet-question"><h3>Question ${i+1}</h3><p>${esc(q.text)}</p>${q.type==='choice'?q.choices.map((c,j)=>`<p>${String.fromCharCode(65+j)}. ${esc(c)}</p>`).join(''):''}<p>Working:</p><br><br></section>`).join('')}${d.memo?`<section style="break-before:page;margin-top:35px"><h2>Worked memo</h2>${qs.map((q,i)=>`<div class="panel"><h3>Question ${i+1}</h3>${q.steps.map(s=>`<p>${esc(s)}</p>`).join('')}</div>`).join('')}</section>`:''}<div class="actions no-print" style="margin-top:25px">${button('print','Print / save as PDF')}${link('educator','← Back to the studio','button secondary')}</div>`;main.focus();return;}
});
document.addEventListener('input',e=>{if(e.target.id==='topic-search')filterTopics();});
function filterTopics(){const s=($('#topic-search')?.value||'').toLowerCase(),paper=$('#paper-filter')?.value||'all';const list=topics.filter(t=>(paper==='all'||!t.paper||t.paper===Number(paper))&&JSON.stringify(t).toLowerCase().includes(s));$('#topic-grid').innerHTML=list.length?cards(list):'<div class="empty"><p>No matching topics. Try a shorter search.</p></div>';}
document.addEventListener('change',async e=>{const a=e.target;if(a.dataset.pref){state.prefs[a.dataset.pref]=a.type==='checkbox'?a.checked:Number(a.value);prefs();return;}
 if(a.id==='paper-filter'){filterTopics();return;}if(a.id==='flash-topic'){flashFilter=a.value;flash=0;flipped=false;render();return;}
 if(a.id==='formula-topic'){$('#formula-display').textContent=topic(a.value).formula;return;}if(a.id==='practice-topic')location.hash='practice/'+a.value+'/0';
 if(a.dataset.task){const t=state.tasks.find(t=>t.id===a.dataset.task);if(t){t.done=a.checked;if(t.done)activity();save();render();}return;}
 if(a.id==='import-file'&&a.files[0]){try{if(a.files[0].size>3000000)throw Error('This backup is too large. Choose an app backup under 3 MB.');const imported=JSON.parse(await a.files[0].text());if(imported.app!==config.id||imported.data?.version!==1)throw Error('Choose a backup from '+config.name+'.');pendingImport=imported.data;if($('#modal').open)close();modal(`<h2>Restore this backup?</h2><p>This replaces the current name, notes, tasks, progress and saved questions on this device.</p><p>${esc(imported.data.name||'Learner')} · ${Array.isArray(imported.data.tasks)?imported.data.tasks.length:0} tasks · ${Array.isArray(imported.data.mastered)?imported.data.mastered.length:0} mastered questions</p><div class="actions">${button('export','Export current work first')}${button('restore','Restore this backup','button')}${button('close','Cancel')}</div>`);}catch(err){toast(err.message);}a.value='';}
});
async function offlineStatus(){const el=$('#offline-status');if(!el)return;if(!('serviceWorker'in navigator)){el.textContent='Offline caching is not supported in this browser.';return;}try{const r=await navigator.serviceWorker.getRegistration();el.textContent=r?.active?'Offline shell installed. External resources still need internet.':'First-load caching is in progress. Revisit after the app has loaded online.';}catch{el.textContent='Offline status is unavailable in this browser.';}}
document.body.dataset.subject=config.subject;
$('#brand').innerHTML=`<img src="icon.svg" width="44" height="44" alt=""><span>${config.name.split(' ').join('<br>')}<small>ONE LITTLE AHA AT A TIME</small></span>`;
$('#navigation').innerHTML=[['home','home','My starting point'],['learn','book','Learn & practise'],['videos','play','Video lessons'],['papers','paper','Past papers'],['lab','lab',config.lab],['exam','check','Mini-mock room'],['revision','cards','Revision toolkit'],['planner','clock','My study plan'],['notebook','note','My notebook'],['progress','chart','My progress'],['buddy','star','Ask '+config.buddy]].map(([r,i,label])=>`<a href="#${r}" data-nav="${r}">${icon(i)}${label}</a>`).join('');
$('#brand').href='#home';$('#subject-label').textContent=config.label+' · GRADE 12';$('#theme').innerHTML=icon('sun');$('#menu').innerHTML=icon('menu');$('#companion').href='../'+config.other+'/';$('#companion').textContent=config.otherName+' ↗';$('#app-tagline').textContent=config.tagline;
window.addEventListener('hashchange',render);window.addEventListener('beforeunload',()=>{saveExamAnswer();save();});window.addEventListener('storage',e=>{if(e.key===key){toast('Study records changed in another tab. Reload to see the latest version.');}});setInterval(tick,1000);prefs();render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{if(route[0]==='about')offlineStatus();});
}
